INSERT INTO `emailtemplate` VALUES ('cms86j7ac0003tsq7jzn37gsl','welcome','Welcome to AccsMarkets.org','<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Welcome to AccsMarkets — Your Marketplace Account Is Ready</title>\n<style>\nbody{margin:0;background:#f4f6f8;font-family:Arial,sans-serif;color:#303846}table{border-collapse:collapse}img{display:block;border:0}a{text-decoration:none}\n.card{max-width:640px;width:100%;background:#fff;border-radius:24px;overflow:hidden;box-shadow:0 14px 40px rgba(23,31,45,.10)}\n.hero{background:linear-gradient(135deg,#ff6a00,#ff4d00 58%,#ff7a1a)}.pulse{animation:pulse 2.4s ease-in-out infinite}.float{animation:float 3.2s ease-in-out infinite}\n@keyframes pulse{0%,100%{transform:scale(1)}50%{transform:scale(1.04)}}@keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}\n@media(prefers-reduced-motion:reduce){.pulse,.float{animation:none}}@media(max-width:680px){.pad{padding-left:22px!important;padding-right:22px!important}.title{font-size:30px!important}.btn{display:block!important;text-align:center!important}}\n</style></head><body>\n<div style=\"display:none;max-height:0;overflow:hidden\">Welcome to AccsMarkets — Your Marketplace Account Is Ready</div>\n<table role=\"presentation\" width=\"100%\"><tr><td align=\"center\" style=\"padding:32px 12px\">\n<table role=\"presentation\" class=\"card\">\n<tr><td class=\"hero pad\" style=\"padding:30px 42px 34px\">\n<table width=\"100%\"><tr><td><a href=\"{{site_url}}\"><img src=\"{{logo_url}}\" width=\"168\" alt=\"AccsMarkets\"></a></td>\n<td align=\"right\"><span class=\"pulse\" style=\"display:inline-block;padding:8px 12px;border-radius:999px;background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.35);color:#fff;font-size:11px;font-weight:700;letter-spacing:.08em\">SECURE MARKETPLACE</span></td></tr></table>\n<div style=\"height:28px\"></div><div style=\"font-size:12px;font-weight:700;letter-spacing:.14em;color:#fff4ec\">WELCOME TO ACCSMARKETS</div>\n<h1 class=\"title\" style=\"margin:10px 0 0;color:#fff;font-size:40px;line-height:1.12;letter-spacing:-.03em\">Your account is ready</h1></td></tr>\n<tr><td class=\"pad\" style=\"padding:34px 42px 12px\"><span class=\"float\" style=\"display:inline-block;padding:9px 14px;border-radius:999px;background:#fff4ed;border:1px solid #ffd7c2;color:#d94700;font-weight:700;font-size:13px\">✓ Account activated</span>\n<p style=\"margin:24px 0 0;font-size:16px;line-height:1.75\">Hi {{user_name}}, welcome to AccsMarkets. Your account has been created successfully and you can now explore listings, publish accounts, and manage secure transactions.</p></td></tr>\n<tr><td class=\"pad\" style=\"padding:24px 42px 10px\"><a class=\"btn\" href=\"{{dashboard_url}}\" style=\"display:inline-block;padding:15px 24px;border-radius:12px;background:#ff5a00;color:#fff;font-weight:700\">Open dashboard &nbsp;→</a></td></tr>\n<tr><td class=\"pad\" style=\"padding:18px 42px 34px\"><div style=\"padding:16px 18px;border-radius:16px;background:#f7f8fa;border:1px solid #e8ebef;color:#667085;font-size:13px;line-height:1.6\">For your security, never share passwords, recovery codes, or two-factor authentication codes.</div></td></tr>\n<tr><td style=\"padding:24px 32px;text-align:center;background:#111827\"><p style=\"margin:0 0 8px;color:#fff;font-weight:700\">AccsMarkets.org</p>\n<p style=\"margin:0;color:#9ca3af;font-size:12px;line-height:1.6\"><a href=\"{{help_url}}\" style=\"color:#ff8a4c\">Help Center</a> · <a href=\"{{privacy_url}}\" style=\"color:#ff8a4c\">Privacy</a> · <a href=\"{{terms_url}}\" style=\"color:#ff8a4c\">Terms</a></p>\n<p style=\"margin:12px 0 0;color:#6b7280;font-size:11px\">© {{current_year}} AccsMarkets. Automated service email.</p></td></tr>\n</table></td></tr></table></body></html>','2026-07-31 00:04:53.131');
