INSERT INTO `listing` VALUES ('cmrz8i0i20004dv3lh7s06ldy','cmrz6qkfk000mvs869uavrwi6','YOUTUBE','https://www.youtube.com/channel/UCYK9hj3UADsw36-R4m12UOw','Islamic YouTube Shorts Channel | 1,150 Subscribers | 65% Engagement','Established YouTube Shorts channel focused on Quranic parables and Islamic educational content. The channel currently has 1,150 subscribers, approximately 65% engagement, and is around one month old. It is not monetized yet, giving the buyer an opportunity to continue growing it toward monetization. The channel has an active Islamic-content audience and strong potential for regular short-form uploads. Selling because I am focusing on other projects. Buyers may review the channel analytics before completing the purchase. Full channel ownership and available related assets will be transferred securely after escrow confirmation.',30.00,1150,65,1,0,331000,0.00,0.00,'Arabic','2026-06-13 00:00:00.000',0,0,'NON','OFF','Quran Parables','[\"https://res.cloudinary.com/ay5pafey/image/upload/v1784915302/accsmarkets/listings/r2txpfplsvtwpqwilpqu.png\",\"https://res.cloudinary.com/ay5pafey/image/upload/v1784915311/accsmarkets/listings/hvtlvbvjn5vjlkemgq52.png\",\"https://res.cloudinary.com/ay5pafey/image/upload/v1784915318/accsmarkets/listings/mbztesnp86eqlq1aghy8.png\",\"https://res.cloudinary.com/ay5pafey/image/upload/v1784915324/accsmarkets/listings/qf5p6krggtxfv1jx8q5d.png\"]','AM-4EE4245A',1,'YOUTUBE_API','2026-07-24 17:48:46.726','UCYK9hj3UADsw36-R4m12UOw','ACTIVE',0,NULL,21,0,0,0,NULL,NULL,NULL,'2026-07-24 17:48:46.730','2026-07-30 20:19:30.415','2026-07-24 22:48:07.370',NULL,'FIXED',0,NULL,NULL,NULL,NULL,NULL,'https://lh3.googleusercontent.com/d/1ya3t0Qm8K-CcumZ21pJTU_MA6q7Z6Ghw','Islamic / Religious'),('cms0psn380007o2f2tm7cufq3','cmrz6qkfk000mvs869uavrwi6','YOUTUBE','https://www.youtube.com/channel/UCqyJi8JzUY2aop0fvwgrdhg','Established YouTube Channel Since 2020 – Music, Entertainment & 4K Content','eat Fission is an established YouTube channel with a content history dating back to 2020. The channel includes videos across lo-fi music, entertainment, movie-related content, and 4K travel footage, with one uploaded video reaching over 4,000 views.\n\nThe channel is currently not monetized, and most existing videos are unlisted or private, giving the new owner flexibility to rebrand it and launch a fresh content strategy. It may suit a buyer interested in music, entertainment, travel, compilations, or faceless YouTube content.\n\nThe branded channel name, logo, existing uploads, and channel history are included. Selling because I am focusing on other projects. Transfer will be completed using YouTube’s proper ownership and permissions process.\n\nImportant: Only add claims such as “no strikes,” “copyright clean,” or “eligible for monetization” after confirming them inside YouTube Studio.',50.00,15400,75,580,1,25000000,3.90,1.50,'English','2019-04-14 00:00:00.000',0,0,NULL,'CHANGEABLE','Beat Fusion','[\"https://lh3.googleusercontent.com/d/1noj2rI7vnSf2VyuNHbOg2l8ydDP4YTq2\",\"https://lh3.googleusercontent.com/d/1XU3yflUvOp6YetJAgt5yPVajZ-1sSsV4\",\"https://lh3.googleusercontent.com/d/10DP0EXgb72T_sKuoet7P_2hh6DDmuY7Z\",\"https://lh3.googleusercontent.com/d/1mT8rV2y9LT9C-P5mUpreuBFZ4XIZzQti\"]','AM-379E6C11',1,'YOUTUBE_API','2026-07-25 18:40:42.199','UCqyJi8JzUY2aop0fvwgrdhg','ACTIVE',0,NULL,12,0,0,0,NULL,NULL,NULL,'2026-07-25 18:40:42.212','2026-07-29 23:36:10.213','2026-07-25 18:40:49.833',NULL,'FIXED',0,NULL,NULL,NULL,NULL,NULL,'https://yt3.ggpht.com/I1BsmnGw3nNTPzYj3Vprv2AbggJcFNWPGflD98MIml2nXPT75uZldHY8WY6i_Hgp3IraK3EwhQ=s240-c-k-c0x00ffffff-no-rj','Music'),('cms3a0ao6000lvhos33opz53l','cmrz6qkfk000mvs869uavrwi6','FACEBOOK','https://www.facebook.com/Quranparaables/','Fully Monetized Quran & Islamic Facebook Page with Content Monetization','Quranparaables ek fully monetized Islamic Facebook page hai jisme Content Monetization active hai. Page par Quranic verses, Islamic reminders, motivational posts aur faith